<script lang="ts">
  import { app, actions, isAdmin, leaveBalance } from '#lib/state/app';
  import PageHeading from '#lib/components/PageHeading.svelte';
  import Icon from '#lib/components/Icon.svelte';
  import { formatDate } from '#lib/domain';
  let address='',emergencyName='',emergencyPhone='',editing=false,busy=false,message='',failed=false;
  let photoFile: File | undefined;
  $: employee=$app.user;
  $: position=$app.positions.find(p=>p.id===employee?.positionId);
  function edit(){if(!employee)return;address=employee.address;emergencyName=employee.emergencyName;emergencyPhone=employee.emergencyPhone;photoFile=undefined;editing=true;}
  async function save(){busy=true;message='';try{await actions.updateProfile({address,emergencyName,emergencyPhone,photoFile});photoFile=undefined;editing=false;failed=false;message='Informasi pribadi diperbarui.';}catch(e){failed=true;message=e instanceof Error?e.message:'Belum berhasil disimpan.';}finally{busy=false;}}
  async function logout(){await actions.logout();}
</script>
<PageHeading eyebrow="AKUN SAYA" title="Profil & informasi kerja" description="Kenali akun Anda dan lengkapi informasi yang dibutuhkan tim."/>
{#if employee}<div class="profile-grid"><section class="panel identity"><span class="portrait">{#if employee.photoUrl}<img src={employee.photoUrl} alt="Foto profil {employee.fullName}"/>{:else}{employee.fullName.split(' ').map(w=>w[0]).slice(0,2).join('')}{/if}</span><h2>{employee.fullName}</h2><p>{position?.name}</p><span class="number">{employee.employeeNumber}</span><div class="balance"><strong>{leaveBalance(employee.id)}</strong><span>hari cuti tersedia</span></div><dl><div><dt>Departemen</dt><dd>{$app.departments.find(d=>d.id===employee.departmentId)?.name}</dd></div><div><dt>Penempatan</dt><dd>{$app.outlets.find(o=>o.id===employee.outletId)?.name}</dd></div><div><dt>Tanggal masuk</dt><dd>{formatDate(employee.joinDate)}</dd></div><div><dt>Hubungan kerja</dt><dd>Tetap</dd></div><div><dt>WhatsApp</dt><dd>{employee.phone}</dd></div></dl><p class="hint">Perubahan data kerja dan WhatsApp dilakukan melalui Admin HR.</p></section><div class="stack"><section class="panel"><div class="section-head"><div><h3>Informasi pribadi</h3><p>Foto, alamat, dan kontak untuk kondisi darurat.</p></div>{#if !editing}<button class="btn btn-secondary" on:click={edit}><Icon name="edit" size={15}/>Edit</button>{/if}</div>{#if message}<div class={failed?'error':'success'} role="status">{message}</div>{/if}{#if editing}<form on:submit|preventDefault={save}><label class="field">Foto profil<input class="input photo-input" type="file" accept="image/jpeg,image/png,image/webp" on:change={event=>photoFile=event.currentTarget.files?.[0]}/><span class="hint">JPG, PNG, atau WebP. Maksimal 5 MB.</span></label><label class="field">Alamat<textarea class="textarea" rows="3" bind:value={address}></textarea></label><div class="form-grid"><label class="field">Nama kontak darurat<input class="input" bind:value={emergencyName}/></label><label class="field">Nomor kontak darurat<input class="input" type="tel" bind:value={emergencyPhone}/></label></div><div class="form-actions"><button class="btn btn-secondary" type="button" disabled={busy} on:click={()=>editing=false}>Batal</button><button class="btn btn-primary" disabled={busy}>{busy?'Menyimpan…':'Simpan perubahan'}</button></div></form>{:else}<dl class="personal"><div><dt>Alamat</dt><dd>{employee.address||'Belum dilengkapi'}</dd></div><div><dt>Kontak darurat</dt><dd>{employee.emergencyName||'Belum dilengkapi'}</dd></div><div><dt>Nomor kontak darurat</dt><dd>{employee.emergencyPhone||'Belum dilengkapi'}</dd></div></dl>{/if}</section>{#if isAdmin(employee)}<section class="panel"><h3>Pengelolaan HR</h3><p class="hint">Akses pengaturan dan rekap dari perangkat Anda.</p><div class="quick-links"><a href="/organization"><Icon name="building"/>Outlet, departemen & jabatan<Icon name="chevron" size={16}/></a><a href="/reports"><Icon name="chart"/>Rekap & riwayat koreksi<Icon name="chevron" size={16}/></a></div></section>{/if}{#if $app.mode==='demo'}<section class="panel demo-panel"><h3>Coba sebagai anggota tim</h3><p class="hint">Pergantian peran hanya tersedia pada data contoh. Data ini tidak digunakan untuk operasional.</p><label class="field">Akun contoh<select class="select" value={employee.id} on:change={e=>actions.switchDemoUser(e.currentTarget.value)}>{#each $app.employees.filter(e=>e.status==='active') as e}<option value={e.id}>{e.fullName} — {$app.positions.find(p=>p.id===e.positionId)?.name}</option>{/each}</select></label></section>{/if}<section class="panel security"><Icon name="shield" size={22}/><div><h3>Keamanan akun</h3><p>Kata sandi Anda bersifat pribadi. Hubungi Admin HR untuk mendapatkan tautan pemulihan jika diperlukan.</p></div></section><button class="btn btn-secondary logout" on:click={logout}><Icon name="logout" size={17}/>Keluar akun</button></div></div>{/if}
<style>
.profile-grid{display:grid;grid-template-columns:320px 1fr;gap:22px}.identity{text-align:center;align-self:start}.portrait{width:80px;height:80px;background:#f1ead3;border-radius:50%;display:grid;place-content:center;font-size:25px;font-weight:600;margin:0 auto 18px}.identity h2{font-size:21px;margin-bottom:7px}.identity>p{font-size:12px;color:var(--muted)}.number{display:inline-block;background:#f8f5eb;padding:6px 11px;border-radius:6px;font-size:10px;letter-spacing:1px}.balance{padding:24px 0;margin:20px 0;border-block:1px solid var(--border);display:flex;flex-direction:column;gap:5px}.balance strong{font-family:Manrope;font-size:36px;font-weight:500}.balance>span{font-size:11px;color:var(--muted)}dl{margin:0}dl>div{display:flex;justify-content:space-between;gap:16px;padding:10px 0;font-size:11px;text-align:left}dt{color:var(--muted);flex-shrink:0}dd{margin:0;text-align:right}.identity>.hint{margin-top:20px;font-size:10px}.section-head{display:flex;justify-content:space-between;gap:14px;align-items:start}h3{font-size:16px;margin-bottom:8px}.section-head p{font-size:11px;color:var(--muted);margin-bottom:24px}.personal>div{flex-direction:column;gap:8px;border-bottom:1px solid var(--border);padding:17px 0;font-size:12px}.personal dd{text-align:left}.personal>div:last-child{border:0}form{display:flex;flex-direction:column;gap:18px}.quick-links{display:flex;flex-direction:column}.quick-links a{display:flex;align-items:center;gap:10px;padding:15px 0;border-bottom:1px solid var(--border);font-size:12px}.quick-links a :global(svg:last-child){margin-left:auto}.quick-links a:last-child{border:0}.demo-panel{background:#f7f3e6}.security{display:flex;gap:15px;align-items:start}.security :global(svg){color:var(--muted);flex-shrink:0}.security p{font-size:11px;color:var(--muted);line-height:1.8;margin:0}.logout{align-self:flex-start}@media(max-width:950px){.profile-grid{grid-template-columns:1fr}.identity dl>div{max-width:400px;margin:auto}}
  .portrait { display: flex; align-items: center; justify-content: center; background: var(--surface); color: var(--accent); border: 1px solid #ffffffa6; box-shadow: var(--raised); border-radius: 25px; overflow: hidden; }
  .portrait img { width: 100%; height: 100%; object-fit: cover; }
  .number { background: var(--surface); color: var(--accent); box-shadow: var(--inset); border-radius: 9px; padding: 8px 12px; }
  .balance strong, h3, .identity h2 { color: var(--ink); }
  .quick-links a { min-height: 48px; color: var(--accent); }
  .demo-panel { background: #f0e8d1; border-color: #f8f5e9; }
  .security :global(svg) { color: var(--accent); }
  .photo-input { padding: 10px; font-size: 12px; } .photo-input::file-selector-button { border: 1px solid #e0d1a1; border-radius: 8px; background: var(--surface); color: var(--accent); padding: 8px 10px; margin-right: 10px; cursor: pointer; font: inherit; font-weight: 600; }
